"""Regenerate DLANTR fixtures using SciPy's independent LAPACK implementation."""

import json
import math
from pathlib import Path

import numpy as np
import scipy
from scipy.linalg.lapack import dlantr


FILENAME = Path(__file__).with_name('data.json')
NORMS = {'max': 'M', 'one': '1', 'infinity': 'I', 'frobenius': 'F'}


def decode(value):
    """Decode non-finite values stored as JSON strings."""
    if value == 'nan':
        return math.nan
    if value == 'pinf':
        return math.inf
    if value == 'ninf':
        return -math.inf
    return value


def encode(value):
    """Encode non-finite values without non-standard JSON numbers."""
    if math.isnan(value):
        return 'nan'
    if math.isinf(value):
        return 'pinf' if value > 0.0 else 'ninf'
    return value


with FILENAME.open(encoding='utf-8') as handle:
    data = json.load(handle)

for record in data['records']:
    matrix = np.array(
        [[decode(x) for x in row] for row in record['A']],
        dtype=np.float64,
        order='F'
    )
    assert matrix.shape == (record['M'], record['N'])
    for name, norm in NORMS.items():
        oracle_result = dlantr(
            norm,
            matrix,
            uplo='U' if record['uplo'] == 'upper' else 'L',
            diag='U' if record['diag'] == 'unit' else 'N'
        )
        record['expected'][name] = encode(oracle_result)

data['provenance'] = (
    'SciPy ' + scipy.__version__ + ' scipy.linalg.lapack.dlantr; '
    'seed12345; independently executed LAPACK oracle'
)
with FILENAME.open('w', encoding='utf-8') as handle:
    json.dump(data, handle, indent=2, allow_nan=False)
    handle.write('\n')
print(
    'Regenerated ' + str(len(data['records'])*len(NORMS)) +
    ' LAPACK results.'
)
